-- Workspace-scoped, revision-aware Fudge intake. Promoted after explicit deployment
-- authorization on 2026-10-28. Filename generated by Supabase CLI 2.122.0.
-- Depends on reporting_foundation; no publishing-protocol dependency.

create function private_reporting.valid_fudge_payload(value jsonb) returns boolean
language plpgsql immutable set search_path = '' as $$
declare field text; photo jsonb;
begin
  if value is null or jsonb_typeof(value) <> 'object' then return false; end if;
  if not (value ?& array['text','rating','author','business_name','place_id','source_url','photo_urls','display_date'])
    or exists(select 1 from jsonb_object_keys(value) k where k not in ('text','rating','author','business_name','place_id','source_url','photo_urls','display_date')) then return false; end if;
  foreach field in array array['text','author','business_name','place_id','source_url','display_date'] loop
    if jsonb_typeof(value->field) <> 'string' then return false; end if;
  end loop;
  if char_length(value->>'text') not between 1 and 30000 or (value->>'text') !~ '[^[:space:]]'
    or char_length(value->>'author') > 300 or char_length(value->>'business_name') > 500
    or char_length(value->>'place_id') > 512 or char_length(value->>'display_date') > 200 then return false; end if;
  if jsonb_typeof(value->'rating') <> 'number' then return false; end if;
  if (value->>'rating')::numeric not between 1 and 5
    or trunc((value->>'rating')::numeric) <> (value->>'rating')::numeric then return false; end if;
  if char_length(value->>'source_url') > 4096 or (value->>'source_url') !~ '^https://[A-Za-z0-9.-]+(:[0-9]{1,5})?([/?#][^[:space:]]*)?$' then return false; end if;
  if jsonb_typeof(value->'photo_urls') <> 'array' then return false; end if;
  if jsonb_array_length(value->'photo_urls') > 30 then return false; end if;
  for photo in select v from jsonb_array_elements(value->'photo_urls') v loop
    if jsonb_typeof(photo) <> 'string' or char_length(photo#>>'{}') > 4096
      or (photo#>>'{}') !~ '^https://[A-Za-z0-9.-]+(:[0-9]{1,5})?([/?#][^[:space:]]*)?$' then return false; end if;
  end loop;
  return octet_length(value::text) <= 131072;
end $$;
revoke all on function private_reporting.valid_fudge_payload(jsonb) from public, anon, authenticated;

create table public.reporting_fudge_records (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.reporting_organizations(id) on delete cascade,
  source text not null check (source = 'google'),
  source_review_id text not null check (char_length(source_review_id) between 1 and 512 and source_review_id = btrim(source_review_id)),
  created_at timestamptz not null default now(),
  unique (organization_id, id),
  unique (organization_id, source, source_review_id)
);

create table public.reporting_fudge_revisions (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null,
  record_id uuid not null,
  revision integer not null check (revision >= 1),
  payload jsonb not null check (private_reporting.valid_fudge_payload(payload)),
  -- Set only by the restricted RPC; convert_to is STABLE, so not a generated expression.
  payload_sha256 text not null check (payload_sha256 ~ '^[0-9a-f]{64}$'),
  observed_at timestamptz not null,
  received_at timestamptz not null default now(),
  received_by uuid references auth.users(id) on delete set null,
  foreign key (organization_id, record_id) references public.reporting_fudge_records(organization_id, id) on delete cascade,
  unique (organization_id, record_id, revision),
  unique (organization_id, record_id, payload_sha256)
);
create index reporting_fudge_revisions_actor on public.reporting_fudge_revisions(received_by);
create index reporting_fudge_records_recent on public.reporting_fudge_records(organization_id, created_at desc, id);

alter table public.reporting_fudge_records enable row level security;
alter table public.reporting_fudge_revisions enable row level security;
create policy fudge_record_staff_read on public.reporting_fudge_records for select to authenticated using (private_reporting.is_staff(organization_id));
create policy fudge_revision_staff_read on public.reporting_fudge_revisions for select to authenticated using (private_reporting.is_staff(organization_id));
revoke all on public.reporting_fudge_records, public.reporting_fudge_revisions from public, anon, authenticated;
grant select on public.reporting_fudge_records, public.reporting_fudge_revisions to authenticated;

-- Privilege escalation is confined to a private implementation with explicit checks.
-- A public SECURITY INVOKER wrapper below provides the narrow authenticated RPC.
create function private_reporting.ingest_fudge_reviews_v1(org uuid, reviews jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare item jsonb; payload_value jsonb; identity_value text; observed timestamptz;
  record_uuid uuid; revision_uuid uuid; revision_value integer; existing_payload jsonb;
  checksum text; inserted_record boolean; inserted_revision boolean; results jsonb := '[]';
begin
  if auth.uid() is null or not private_reporting.is_staff(org)
    or not exists(select 1 from auth.users where id=auth.uid() and email_confirmed_at is not null) then
    raise exception 'Verified workspace staff required' using errcode='42501';
  end if;
  if reviews is null or jsonb_typeof(reviews) <> 'array' then raise exception 'reviews must be an array'; end if;
  if jsonb_array_length(reviews) not between 1 and 100 or octet_length(reviews::text) > 524288 then raise exception 'Batch exceeds count or byte limits'; end if;
  -- Conservative initial serialization: no race in revision numbering/first insert.
  -- Transaction scoped; hash collisions can serialize unrelated work but cannot share data.
  perform pg_advisory_xact_lock(hashtextextended(org::text, 20261028));
  if not private_reporting.is_staff(org) then raise exception 'Verified workspace staff required' using errcode='42501'; end if;
  for item in select v from jsonb_array_elements(reviews) v loop
    if jsonb_typeof(item) <> 'object' or not (item ?& array['source','source_review_id','observed_at','payload'])
      or exists(select 1 from jsonb_object_keys(item) k where k not in ('source','source_review_id','observed_at','payload')) then raise exception 'Invalid review envelope'; end if;
    if jsonb_typeof(item->'source') <> 'string' or item->>'source' <> 'google'
      or jsonb_typeof(item->'source_review_id') <> 'string'
      or char_length(item->>'source_review_id') not between 1 and 512
      or item->>'source_review_id' <> btrim(item->>'source_review_id')
      or item->>'source_review_id' ~ '[[:space:][:cntrl:]]' then raise exception 'Stable Google review identity required'; end if;
    identity_value := item->>'source_review_id';
    if (select count(*) from jsonb_array_elements(reviews) v where v->>'source_review_id'=identity_value) > 1 then raise exception 'Duplicate identity within batch'; end if;
    if jsonb_typeof(item->'observed_at') <> 'string' or item->>'observed_at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$' then raise exception 'Zoned observation timestamp required'; end if;
    begin observed := (item->>'observed_at')::timestamptz;
    exception when others then raise exception 'Invalid observation timestamp'; end;
    if observed > now() + interval '5 minutes' then raise exception 'Observation timestamp is in the future'; end if;
    payload_value := item->'payload';
    if not private_reporting.valid_fudge_payload(payload_value) then raise exception 'Invalid allowlisted source payload'; end if;
    -- Normalize only rating's numeric representation for hashing (5 = 5.0).
    -- Store the submitted payload itself unchanged.
    checksum := encode(sha256(convert_to(jsonb_set(payload_value, '{rating}', to_jsonb((payload_value->>'rating')::numeric::integer))::text, 'UTF8')), 'hex');
    record_uuid := null;
    insert into public.reporting_fudge_records(organization_id, source, source_review_id)
      values(org, 'google', identity_value) on conflict (organization_id, source, source_review_id) do nothing returning id into record_uuid;
    inserted_record := record_uuid is not null;
    if record_uuid is null then select id into strict record_uuid from public.reporting_fudge_records where organization_id=org and source='google' and source_review_id=identity_value; end if;
    revision_uuid := null;
    select id, revision, payload into revision_uuid, revision_value, existing_payload from public.reporting_fudge_revisions
      where organization_id=org and record_id=record_uuid and payload_sha256=checksum;
    inserted_revision := revision_uuid is null;
    if inserted_revision then
      select coalesce(max(revision),0)+1 into revision_value from public.reporting_fudge_revisions where organization_id=org and record_id=record_uuid;
      insert into public.reporting_fudge_revisions(organization_id,record_id,revision,payload,payload_sha256,observed_at,received_by)
        values(org,record_uuid,revision_value,payload_value,checksum,observed,auth.uid()) returning id into revision_uuid;
    elsif existing_payload <> payload_value then
      raise exception 'Payload checksum conflict; manual reconciliation required';
    end if;
    results := results || jsonb_build_array(jsonb_build_object('source','google','source_review_id',identity_value,
      'record_id',record_uuid,'revision_id',revision_uuid,'revision',revision_value,'inserted_record',inserted_record,'inserted_revision',inserted_revision));
  end loop;
  return results;
end $$;
revoke all on function private_reporting.ingest_fudge_reviews_v1(uuid,jsonb) from public, anon, authenticated;
grant execute on function private_reporting.ingest_fudge_reviews_v1(uuid,jsonb) to authenticated;

create function public.reporting_ingest_fudge_reviews_v1(org uuid, reviews jsonb) returns jsonb
language sql security invoker set search_path = '' as $$
  select private_reporting.ingest_fudge_reviews_v1(org, reviews);
$$;
revoke all on function public.reporting_ingest_fudge_reviews_v1(uuid,jsonb) from public, anon, authenticated;
grant execute on function public.reporting_ingest_fudge_reviews_v1(uuid,jsonb) to authenticated;

comment on table public.reporting_fudge_records is 'Workspace-owned source identities. Intake does not assign a customer, approve content, publish or synchronize Sheets.';
comment on table public.reporting_fudge_revisions is 'Append-only client-visible allowlisted source revisions. First payload and original text are never overwritten by this protocol; identical content replays reuse its revision. observed_at is the first accepted observation for that content, not last-seen or a publication time.';
notify pgrst, 'reload schema';
